/**
 * Variation IDs whose parent product belongs to the given terms.
 *
 * @param int[]  $term_ids Term IDs.
 * @param string $taxonomy product_cat or product_tag.
 * @return int[]
 */
function perfectpixel_get_variation_ids_by_term( $term_ids, $taxonomy = 'product_cat' ) {
	$parents = wc_get_products(
		array(
			'type'   => 'variable',
			'status' => 'publish',
			'limit'  => -1,
			'return' => 'ids',
			'tax_query' => array(
				array(
					'taxonomy' => $taxonomy,
					'field'    => 'term_id',
					'terms'    => array_map( 'intval', (array) $term_ids ),
				),
			),
		)
	);
	if ( ! $parents ) {
		return array();
	}
	return array_map(
		'intval',
		get_posts(
			array(
				'post_type'       => 'product_variation',
				'post_status'     => array( 'publish', 'private' ),
				'post_parent__in' => $parents,
				'fields'          => 'ids',
				'posts_per_page'  => -1,
				'no_found_rows'   => true,
			)
		)
	);
}
